    rb = [-1] + sep_rows + [h]
    cb = [-1] + sep_cols + [w]
    row_cells = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_cells = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    seeds = {}
    for i, (r0, r1) in enumerate(row_cells):
        for j, (c0, c1) in enumerate(col_cells):
            vals = {grid[r][c] for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] not in (0, 8)}
            if vals:
                seeds[(i, j)] = next(iter(vals))
    out = [row[:] for row in grid]
    paints = {}
    def add(i, j, color):
        paints.setdefault((i, j), set()).add(color)
    # Connect collinear markers of the same color, only between the outermost markers.
    for color in set(seeds.values()):
        for i in range(len(row_cells)):
            cols = sorted(j for (ri, j), v in seeds.items() if ri == i and v == color)
            if len(cols) >= 2:
                for j in range(cols[0], cols[-1] + 1):
                    add(i, j, color)
        for j in range(len(col_cells)):
            rows = sorted(i for (i, cj), v in seeds.items() if cj == j and v == color)
            if len(rows) >= 2:
                for i in range(rows[0], rows[-1] + 1):
                    add(i, j, color)
    for (i, j), colors in paints.items():
        value = 1
        for color in colors:
            value *= color
        r0, r1 = row_cells[i]
        c0, c1 = col_cells[j]
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = value
    return out
